<?php use App\Core\Security;require BASE_PATH.'/app/Views/layout/header.php';?><div class="d-flex justify-content-between mb-3"><div><h2>Book acquisitions</h2><p class="text-muted">Record purchases, donations, and incoming stock.</p></div><a class="btn btn-pink" href="<?= BASE_URL ?>/?page=acquisitions&action=create">+ Record acquisition</a></div><div class="card p-3"><table class="table"><thead><tr><th>Book</th><th>Supplier</th><th>Quantity</th><th>Unit cost</th><th>Date</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?= Security::e($r['title']) ?></td><td><?= Security::e($r['supplier']) ?></td><td><?= (int)$r['quantity'] ?></td><td>₱<?= number_format((float)$r['unit_cost'],2) ?></td><td><?= Security::e($r['acquired_at']) ?></td><td><form method="post" action="<?= BASE_URL ?>/?page=acquisitions&action=delete" onsubmit="return confirm('Delete this acquisition record? Inventory quantities will not change.');"><input type="hidden" name="_csrf" value="<?= Security::csrf() ?>"><input type="hidden" name="id" value="<?= $r['id'] ?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div><?php require BASE_PATH.'/app/Views/layout/footer.php';?>
